  function syncStretchTask(item){if(!item.done)return;let id=`stretch-${item.date}`,existing=data.tasks.find(t=>t.domain==='stretch'&&t.date===item.date);if(existing){existing.status='done';existing.planned=item.planned;existing.actual=item.actual;existing.link=item.link||existing.link;existing.notes=item.wellbeing||existing.notes;if(item.sessionId)existing.linkedSessionId=item.sessionId;return;}if(!data.tasks.some(t=>t.id===id))data.tasks.push({id,title:'Растяжка — '+(item.actual||item.planned)+' минут',domain:'stretch',date:item.date,start:item.start||'',end:item.end||'',planned:item.planned,actual:item.actual,status:'done',priority:'обычный',link:item.link||'',notes:item.wellbeing||'',linkedSessionId:item.sessionId||''});}
  function saveTaskForm(form){let fd=new FormData(form),o=Object.fromEntries(fd.entries());o.id=o.id||newId();o.planned=Number(o.planned||0);o.actual=Number(o.actual||0);let prior=data.tasks.find(t=>t.id===o.id);if(!validClock(o.start))o.start=validClock(prior?.start)?prior.start:validClock(o.end)?clockAt(Number(o.end.slice(0,2))*60+Number(o.end.slice(3))-(o.planned||30)):'20:30';if(!validClock(o.end))o.end=clockAt(Number(o.start.slice(0,2))*60+Number(o.start.slice(3))+(o.planned||30));if(o.domain==='dance'){o.group=o.group||'IZ*ONE';o.danceTitle=o.danceTitle||'';if(o.danceTitle)o.title=`${o.group} — ${o.danceTitle}`;}else{delete o.group;delete o.danceTitle;}let clash=data.tasks.find(t=>t.id!==o.id&&t.date===o.date&&t.start&&o.start&&t.start<o.end&&t.end>o.start);let wk=parseDate(o.date).getDay(),workdays=(Array.isArray(data.settings.workdays)?data.settings.workdays:[1,2,3,4,5]).map(x=>x%7);let isWork=workdays.includes(wk);let from=data.settings.leave||'09:00',to=data.settings.return||'20:00';if(isWork&&o.start<to&&o.end>from){if(!confirm('Задача попадает в рабочее время или дорогу по текущим настройкам. Всё равно сохранить?'))return;}if(clash&&!confirm(`В это время уже стоит «${clash.title}». Сохранить с конфликтом?`))return;let i=data.tasks.findIndex(t=>t.id===o.id);if(i>=0){if(data.tasks[i].programDay)o.programDay=data.tasks[i].programDay;data.tasks[i]=o;}else data.tasks.push(o);if(o.programDay)syncChloeTask(o,o.status==='done');save();closeModal();render();toast('Задача сохранена.');}
  function saveSettings(form){let fd=new FormData(form),s=Object.fromEntries(fd.entries());s.workdays=[...form.querySelectorAll('[name=workdays]:checked')].map(x=>Number(x.value));s.stretchMinutes=Number(s.stretchMinutes||20);data.settings={...data.settings,...s};save();render();toast('Настройки сохранены.');}
  function deleteBy(type,id){if(!confirm('Удалить эту запись? Это действие нельзя отменить.'))return;let key={task:'tasks',session:'sessions',diary:'diary',goal:'goals'}[type];if(key)data[key]=data[key].filter(x=>x.id!==id);else if(type.startsWith('item:')){let k=type.slice(5),item=(data.items[k]||[]).find(x=>x.id===id);data.items[k]=(data.items[k]||[]).filter(x=>x.id!==id);if(item?.sessionId){data.sessions=data.sessions.filter(s=>s.id!==item.sessionId);data.tasks.forEach(t=>{if(t.linkedSessionId===item.sessionId){t.linkedSessionId='';t.status='planned';t.actual=0;}});}}if(type==='session')data.tasks.forEach(t=>{if(t.linkedSessionId===id){t.linkedSessionId='';t.status='planned';t.actual=0;}});if(type==='task')data.sessions.forEach(s=>{if(s.taskId===id)s.taskId='';});save();closeModal();render();toast('Запись удалена.');}
