    if(t.dataset.cal){let d=parseDate(calDate);if(t.dataset.cal==='today')calDate=today();else if(calMode==='month')d.setMonth(d.getMonth()+(t.dataset.cal==='next'?1:-1));else d.setDate(d.getDate()+(t.dataset.cal==='next'?(calMode==='week'?7:1):-(calMode==='week'?7:1)));if(t.dataset.cal!=='today')calDate=iso(d);render();return;}
    if(t.dataset.action){let a=t.dataset.action;if(a==='new-task')taskForm({},calDate);if(a==='new-session')sessionForm();if(a==='new-diary')diaryForm();if(a==='new-goal')goalForm({month:today().slice(0,7)});if(a==='new-item')newItemForm(t.dataset.kind);if(a==='timer'){if(data.timer)stopTimer();else startTimerForm();}if(a==='export')exportData();if(a==='import')$('#backupFile').click();if(a==='rebuild')rebuild();if(a==='reset'&&confirm('Удалить все записи, цели и настройки из этого браузера? Это действие нельзя отменить.')){data=initial();save();render();toast('Локальные данные удалены.');}if(a==='start-chloe')startChloe();return;}
