  function startChloe(){let start=prompt('Дата первого дня программы (ГГГГ-ММ-ДД).');if(!start)return;if(!/^\d{4}-\d{2}-\d{2}$/.test(start)||Number.isNaN(parseDate(start).getTime())){alert('Укажи дату в формате ГГГГ-ММ-ДД.');return;}data.tasks=data.tasks.filter(t=>!t.programDay);let d=parseDate(start);data.chloeDays.forEach((x,i)=>{let dd=new Date(d);dd.setDate(dd.getDate()+i);x.date=iso(dd);delete x.completedAt;x.workoutChecks=[];x.sessionId='';let p=chloePlan[i];Object.assign(x,{officialMinutes:p.minutes,planned:p.minutes,items:p.items,restDay:!!p.rest,status:p.rest?'rest':'planned',actual:0});if(!p.rest){let date=iso(dd),weekend=[0,6].includes(dd.getDay()),startTime=weekend?'14:00':'20:00',endMin=Number(startTime.slice(0,2))*60+Number(startTime.slice(3))+p.minutes,endTime=`${String(Math.floor(endMin/60)).padStart(2,'0')}:${String(endMin%60).padStart(2,'0')}`;data.tasks.push({id:newId(),title:`Chloe Ting — день ${i+1}`,domain:'chloe',date,start:startTime,end:endTime,planned:p.minutes,actual:0,status:'planned',priority:'обычный',link:x.link,notes:p.items,programDay:i+1,autoTemplate:true});if(!weekend){let stretch=data.tasks.find(t=>t.date===date&&t.domain==='stretch'&&t.autoTemplate),korean=data.tasks.find(t=>t.date===date&&t.domain==='korean'&&t.autoTemplate),dance=data.tasks.find(t=>t.date===date&&t.domain==='dance'&&t.autoTemplate);let move=(task,start,mins)=>{if(task){let n=Number(start.slice(0,2))*60+Number(start.slice(3));task.start=start;task.end=`${String(Math.floor((n+mins)/60)).padStart(2,'0')}:${String((n+mins)%60).padStart(2,'0')}`;}};let n=endMin+5;move(stretch,`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`,20);n+=25;move(korean,`${String(Math.floor(n/60)).padStart(2,'0')}:${String((n)%60).padStart(2,'0')}`,30);n+=35;move(dance,`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`,60);}}});save();render();toast('Даты, дни тренировок и отдыха назначены.');}
  function stopTimer(){if(!data.timer)return;let t=data.timer;let mins=Math.max(1,Math.round((Date.now()-t.started)/60000));data.timer=null;save();sessionForm({domain:t.domain,material:t.material,date:today(),start:new Date(t.started).toTimeString().slice(0,5),end:new Date().toTimeString().slice(0,5),minutes:mins,link:t.link});}
  view.addEventListener('click',handleClick);$('#nav').addEventListener('click',handleClick);modalRoot.addEventListener('click',e=>{let koreanFinish=e.target.closest('[data-confirm-korean-day]');if(koreanFinish){completeKoreanDay(koreanFinish.dataset.confirmKoreanDay);return;}let stretchFinish=e.target.closest('[data-confirm-stretch-week]');if(stretchFinish){completeStretchWeek(Number(stretchFinish.dataset.confirmStretchWeek));return;}let finish=e.target.closest('[data-confirm-chloe-finish]');if(finish){completeChloeDay(finish.dataset.confirmChloeFinish);return;}let ask=e.target.closest('[data-finish-chloe]');if(ask){confirmChloeFinish(ask.dataset.finishChloe);return;}let close=e.target.closest('[data-close]');if(close){closeModal();return;}let preset=e.target.closest('[data-task-preset]');if(preset){let form=modalRoot.querySelector('#taskForm');if(form){let values={korean:['Корейский',30,'20:30'],dance:['Танцы',60,'20:30'],vocal:['Вокал',60,'10:00'],stretch:['Растяжка',20,'20:30'],chloe:['Тренировка',60,'20:00']}[preset.dataset.taskPreset];if(values){let [title,minutes,start]=values;form.elements.domain.value=preset.dataset.taskPreset;form.elements.title.value=title;let df=form.querySelector('#danceTaskFields');if(df){df.style.display=preset.dataset.taskPreset==='dance'?'grid':'none';if(preset.dataset.taskPreset==='dance'){form.elements.group.value='IZ*ONE';form.elements.danceTitle.value='';form.elements.title.value='Танцы — 1 час';}}form.elements.planned.value=minutes;form.elements.start.value=start;let [h,m]=start.split(':').map(Number),end=h*60+m+minutes;form.elements.end.value=`${String(Math.floor(end/60)).padStart(2,'0')}:${String(end%60).padStart(2,'0')}`;}}return;}let b=e.target.closest('[data-delete-task],[data-delete-item]');if(b){if(b.dataset.deleteTask)deleteBy('task',b.dataset.deleteTask);else{let [k,id]=b.dataset.deleteItem.split(':');deleteBy(`item:${k}`,id);}}});
  modalRoot.addEventListener('click',e=>{let button=e.target.closest('#taskForm .modal-actions .btn.primary');if(!button)return;e.preventDefault();let form=button.closest('form');try{saveTaskForm(form);}catch(err){console.error(err);toast('Не удалось сохранить задачу. Проверь данные и попробуй снова.');}});
